public class Solution {
    public boolean hasCycle(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                return true;
            }
        }

        return false;
    }
}

import java.util.*;

public class Solution {
    public boolean hasCycle(ListNode head) {
        Set<ListNode> visited = new HashSet<>();
        ListNode curr = head;

        while (curr != null) {
            if (!visited.add(curr)) {
                return true;
            }
            curr = curr.next;
        }

        return false;
    }
}

public class Solution {
    public boolean hasCycle(ListNode head) {
        if (head == null) {
            return false;
        }

        ListNode checkpoint = head;
        ListNode runner = head.next;
        int power = 1;
        int steps = 1;

        while (runner != null) {
            if (runner == checkpoint) {
                return true;
            }
            if (steps == power) {
                checkpoint = runner;
                power *= 2;
                steps = 0;
            }
            runner = runner.next;
            steps++;
        }

        return false;
    }
}

public class Solution {
    public boolean hasCycle(ListNode head) {
        ListNode sentinel = new ListNode(0);
        ListNode curr = head;

        while (curr != null) {
            if (curr.next == sentinel) {
                return true;
            }
            ListNode next = curr.next;
            curr.next = sentinel;
            curr = next;
        }

        return false;
    }
}
